mapper.select:
select sat.task_id, sat.business_table, sat.business_id, sat.business_details,sat.sub_time, IFNULL((SELECT real_name from auth_info where user_id = sat.sub_per and del_flag='0' and auth_status = '5' order by auth_time desc limit 1),IFNULL(su.nick_name,su.user_name)) as sub_per, sat.audit_id, sat.now_check_step, sat.check_time, sat.check_status, sat.create_by, sat.create_time, sat.update_by, sat.update_time, sat.del_flag, sat.user_id, sat.org_id,sat.video_ids, samc.audit_title,samc.audit_type,sac.level_name from sys_audit_task sat LEFT JOIN sys_user su on su.user_id = sat.sub_per LEFT JOIN sys_audit_main_config samc on samc.audit_id = sat.audit_id LEFT JOIN sys_audit_config sac on sat.now_check_step = sac.config_id WHERE sat.del_flag = '0' and sat.check_status != '3'
and samc.audit_type = #{auditType}
and samc.audit_title like concat('%', #{auditTitle} ,'%')
AND (su.nick_name like concat('%',#{subPer},'%') OR su.user_name like concat('%',#{subPer},'%') OR ((SELECT real_name from auth_info where user_id = sat.sub_per order by auth_time desc limit 1) like concat('%',#{subPer},'%')))
and sat.check_status = #{checkStatus}
order by sat.check_time desc,sat.task_id desc

select sat.task_id, sat.business_table, sat.business_id, sat.business_details,sat.sub_time, IFNULL((SELECT real_name from auth_info where user_id = sat.sub_per and del_flag='0' and auth_status = '5' order by auth_time desc limit 1),IFNULL(su.nick_name,su.user_name)) as sub_per, sat.audit_id, sat.now_check_step, sat.video_ids,sats.check_time, sats.check_status, sats.create_by, sats.create_time, sats.update_by, sats.update_time, sat.del_flag, sat.user_id, sat.org_id,sut.nick_name as check_per, sats.check_opinion,samc.audit_title,samc.audit_type,sac.level_name FROM sys_audit_task_subinfo sats LEFT JOIN sys_audit_task sat on sat.task_id = sats.task_id LEFT JOIN sys_user su on su.user_id = sat.sub_per LEFT JOIN sys_user sut on sats.check_per = sut.user_id LEFT JOIN sys_audit_config sac on sats.audit_config_id = sac.config_id LEFT JOIN sys_audit_main_config samc on samc.audit_id = sac.audit_id where sats.del_flag = '0'
and samc.audit_type = #{auditType}
and samc.audit_title like concat('%', #{auditTitle},'%')
and sats.check_per = #{checkPer}
AND (su.nick_name like concat('%',#{subPer},'%') OR su.user_name like concat('%',#{subPer},'%') OR ((SELECT real_name from auth_info where user_id = sat.sub_per order by auth_time desc limit 1) like concat('%',#{subPer},'%')))
and sats.check_status = #{checkStatus}
order by sat.check_time desc,sats.sub_id desc

select.where:
and del_flag = '0'
 and business_table = #{businessTable}
 and business_id = #{businessId}
 and sub_time = #{subTime}
 and sub_per = #{subPer}
 and audit_id = #{auditId}
 and now_check_step = #{nowCheckStep}
 and check_time = #{checkTime}
 and check_status = #{checkStatus}
 and user_id = #{userId}
 and org_id = #{orgId}

