update sys_audit_task
business_table = #{businessTable}, business_id = #{businessId}, business_details = #{businessDetails}, sub_time = #{subTime}, sub_per = #{subPer}, audit_id = #{auditId}, now_check_step = #{nowCheckStep}, check_time = #{checkTime}, check_status = #{checkStatus}, video_ids = #{videoIds}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, user_id = #{userId}, org_id = #{orgId},
where task_id = #{taskId}
